mapper.select:
FROM TB_TRAVEL TR LEFT JOIN TB_REGION RE ON TR.REGION_NO = RE.REGION_NO LEFT JOIN TB_REG_THEME TRT ON TRT.TRAVEL_NO = TR.TRAVEL_NO LEFT JOIN TB_THEME TH ON TH.THEME_NO = TRT.THEME_NO
AND TR.REGION_NO = #{query.regionNo}
AND TH.THEME_NO = #{query.themeNo}
AND TR.TRAVEL_STATUS = 'N'
ORDER BY TR.COUNT DESC
